// Welcome tour: shown once per device on first launch and on demand from Settings.
// Keep these steps in sync with the app. When a page is added, renamed or removed, or a headline feature changes, update this list (see info.md).
import {esc,icon} from './ui.js';
export const tourSteps=[
 {icon:'check',title:'Welcome to Kinetic',body:'A private journal for your training, food and body. Everything you log stays in this browser on this device. Nothing is uploaded.',points:[]},
 {icon:'overview',title:'Today',body:'Your day at a glance.',points:['A muscle map of everything you trained in the last 7 days','Your next program session, or a suggested workout and the program we recommend if you haven’t started one','Calories and protein logged against your targets','Your weight trend and this week’s sessions','The + button in the corner logs calories, weight, a set, a walk or sleep from any page']},
 {icon:'training',title:'Training',body:'Where you log workouts.',points:['A suggested workout built from what you trained this week, your equipment and your experience. Pick a focus or ask for different exercises','Every workout shows a map of the muscles it works','Focus mode shows one set at a time with the load, reps and plates to put on the bar','Tick a set and the rest timer starts on its own','Missing some equipment? Swap an exercise and the workout rebalances itself']},
 {icon:'anatomy',title:'Muscle atlas',body:'The heart of Kinetic. It’s in the main menu and the bottom bar as Muscles.',points:['Tap any muscle to see what trains it and how much you’ve done','Switch the overlay to see this week’s sets, recent activity or one exercise','The same map appears on Today, in workouts, programs, focus mode and every exercise']},
 {icon:'plan',title:'Plan',body:'Decide what you’ll do before you get to the gym.',points:['Start a recommended program matched to your days, goal and equipment','It tells you what to lift each session and raises the target as you improve','Or build your own routines and schedule them']},
 {icon:'insights',title:'Track',body:'Body, Calories, Cardio, Insights and Goals.',points:['Body: weigh-ins, measurements, body-fat readings and a photo studio','Calories: quick totals with optional protein, and a daily target that updates by itself when your weight, activity or goal changes (or set your own)','Cardio: activities, plus optional sleep and recovery notes','Insights: charts and personal records from everything you log','Goals: set a target and see how far along you are']},
 {icon:'exercises',title:'Library',body:'Exercises and Sources.',points:['Nearly 200 exercises with technique notes, a muscle map and ranked substitutes. Search by name, muscle or equipment','Most movements come in barbell, dumbbell, kettlebell, cable, machine, band and bodyweight versions, so swaps only suggest what you own','Prefer heavier sets of fewer reps, or lighter sets of more? Set it for one exercise from its page','The research behind every number the app shows']},
 {icon:'settings',title:'Settings and backups',body:'Change your units, goal, equipment and rep range preference in Settings, or run the first-time setup again from Settings → About. Your journal exists only on this device, so export a backup regularly. You can also lock it with a passphrase. Once a day Kinetic checks for a newer version and tells you if one is out; it never updates itself, and you can turn the check off in Settings.',points:[]}
];
export function startTour(C,index=0){
 const d=document.querySelector('#modal'),last=tourSteps.length-1;
 const paint=i=>{const s=tourSteps[i];
  d.setAttribute('aria-labelledby','modal-title');
  d.innerHTML=`<div class="modal-header"><h2 id="modal-title">Welcome tour</h2><button type="button" class="btn ghost small" data-tour="close" aria-label="Close tour">${icon('close')}</button></div><div class="modal-body tour"><div class="tour-icon">${icon(s.icon)}</div><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p>${s.points.length?`<ul class="detail-list">${s.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}<div class="tour-dots" role="img" aria-label="Step ${i+1} of ${tourSteps.length}">${tourSteps.map((_,n)=>`<i class="${n===i?'on':''}"></i>`).join('')}</div><div class="modal-footer">${i===0?'<button type="button" class="btn" data-tour="close">Skip</button>':'<button type="button" class="btn" data-tour="back">Back</button>'}${i===last?'<button type="button" class="btn" data-tour="settings">Open Settings</button><button type="button" class="btn primary" data-tour="close">Done</button>':'<button type="button" class="btn primary" data-tour="next">Next</button>'}</div></div>`;
  d.querySelectorAll('[data-tour]').forEach(b=>b.onclick=()=>{const a=b.dataset.tour;if(a==='next')paint(i+1);else if(a==='back')paint(i-1);else{d.close();if(a==='settings')location.hash='settings'}});
  d.querySelector('.btn.primary').focus({preventScroll:true})};
 C.setPref('tourSeen',true);d.onclose=()=>document.querySelector('#main')?.focus({preventScroll:true});
 paint(Math.min(Math.max(index,0),last));if(!d.open)d.showModal();
}
